loop.source:
int x = 0
int hits = 0
while x < 3 {
if x == 0 { set hits = hits + 1 }
set x = x + 1
}

condition_effect.source:
int x = 0
int result = 0
fn change() -> int { set x = 1
return 1 }
if change() == 1 { if x == 0 { set result = 99 } else { set result = 1 } }

argument_effect.source:
int x = 0
int result = 0
fn change() -> int { set x = 1
return 1 }
fn consume(n: int) -> none { }
consume(change())
if x == 0 { set result = 99 } else { set result = 1 }

dictionary_parameter.source:
dict[int] a = {"x": 1}
fn mutate(d: dict[int]) -> none { set d["x"] = 2 }
mutate(a)
int result = a["x"]

dictionary_side_effect.source:
dict[int] d = {"x": 0, "y": 0}
fn change() -> int { set d["y"] = 9
return 1 }
set d["x"] = change()

const_alias.source:
const dict[int] a = {"x": 1}
dict[int] b = a
set b["x"] = 2

const_branch.source:
fn f(n: int) -> int {
if n == 1 { const int x = 1 } else { const int x = 2 }
set x = 3
return x
}
int result = f(1)

reachable_return.source:
fn f(n: int) -> int {
if n == 1 { return 1 } else { int x = 2 }
return x
}
int result = f(0)

recursion_say.source:
fn f() -> str {
say { f() }
return "x"
}

finite_while_return.source:
fn f() -> int {
int x = 0
while x < 1 { set x = x + 1 }
}
int result = f()

struct_return.source:
struct User {
name: str
}
fn f(u: User) -> User { return u }
User a = {"name": "A"}
User b = f(a)

